castLongCloseSyntax peg'n =
  if PegRt.syntaxKind peg'n PegPrelude.== syntaxKindLongClose then PegPrelude.Just (LongCloseSyntax peg'n) else PegPrelude.Nothing

-- | The children bound to @e@ in the rule @LongClose@.
longCloseE :: LongCloseSyntax -> [PegRt.SyntaxElement]
longCloseE (LongCloseSyntax peg'n) = PegRt.labeledElements isTriviaSyntaxKind (PegRt.labelText "e") peg'n

